package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var x int64
	fmt.Fscan(reader, &x)
	a := ((-x)%360 + 360) % 360
	best := 0
	bestDev := int64(1000)
	for k := int64(0); k < 4; k++ {
		r := (a + 90*k) % 360
		dev := r
		if 360-r < dev {
			dev = 360 - r
		}
		if dev < bestDev {
			bestDev = dev
			best = int(k)
		}
	}
	fmt.Println(best)
}
